window.docContents[199].resolve({"/References/#Type-Systems--References___-Typing-Mutable-References--Properties--Progress":{"contents":"As we've said, progress for this system is pretty easy to prove;\nthe proof is very similar to the proof of progress for the STLC,\nwith a few new cases for the new syntactic constructs.\n\ntheorem progress (δ : StoreTy) (t : Tm) (τ : Ty) (ρ : Store)\n  (hTy : <{ ∅ / δ ⊢ t ⦂ τ }>)\n  (hStoreTy : δ ⊢ ρ) :\n  (t.IsValue ∨ ∃ t' ρ', t / ρ ⟶ t' / ρ') := by\n    have ⟨hLen, _⟩ := hStoreTy\n    generalize heq : (∅ : Context) = Γ at hTy\n    induction hTy with (subst_vars; first\n      | contradiction\n      -- discharge cases where `t` is obviously a value\n      | try (left; constructor; done))\n    | app h₁ _ ih₁ ih₂ =>\n      right; cases ih₁ (by rfl) with\n      -- t₁ is a value\n      | inl hv₁ =>\n        cases ih₂ (by rfl) with\n        -- t₂ is a value\n        | inl hv₂ =>\n          cases hv₁ <;> try contradiction\n          apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n        -- t₂ steps\n        | inr hs₂ =>\n          have ⟨t₂', ρ', hs₂⟩ := hs₂\n          apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n      -- t₁ steps\n      | inr hs₁ =>\n        have ⟨t₁', ρ', hs₁⟩ := hs₁\n        apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n    | succ h ih\n    | pred h ih =>\n      -- these two cases are the same\n      right; cases ih (by rfl) with\n      -- t₁ is a value\n      | inl hv =>\n        cases hv <;> try contradiction\n        apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n      -- t₁ steps\n      | inr hs =>\n        have ⟨t₁', ρ', hs⟩ := hs\n        apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n    | mult h₁ h₂ ih₁ ih₂ =>\n      right; cases ih₁ (by rfl) with\n      -- t₁ is a value\n      | inl hv₁ =>\n        cases ih₂ (by rfl) with\n        -- t₂ is a value\n        | inl hv₂ =>\n          cases hv₁ <;> try contradiction\n          cases hv₂ <;> try contradiction\n          apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n        -- t₂ steps\n        | inr hs₂ =>\n          have ⟨t₂', ρ', hs₂⟩ := hs₂\n          apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n      -- t₁ steps\n      | inr hs₁ =>\n        have ⟨t₁', ρ', hs₁⟩ := hs₁\n        apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n    | ite0 h₁ _ _ ih₁ _ _ =>\n      right; cases ih₁ (by rfl) with\n      -- t₁ is a value\n      | inl hv₁ =>\n        cases hv₁ with (try contradiction)\n        | nat n =>\n          cases n <;> (apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval)\n      -- t₁ steps\n      | inr hs₁ =>\n        have ⟨t₁', ρ', hs₁⟩ := hs₁\n        apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n    | ref_ _ ih =>\n      right; cases ih (by rfl) with\n      -- t₁ is a value\n      | inl hv =>\n        apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n      -- t₁ steps\n      | inr hs =>\n        have ⟨t₁', ρ', hs⟩ := hs\n        apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n    | deref h ih =>\n      right; cases ih (by rfl) with\n      -- t₁ is a value; its typing tells us `l < δ.length`\n      | inl hv =>\n        cases hv with (inversion h)\n        | loc_ l => exists ρ[l], ρ; apply Step.derefLoc; lia\n      -- t₁ steps\n      | inr hs =>\n        have ⟨t₁', ρ', hs⟩ := hs\n        apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n    | @assign _ _ t₂ _ h₁ _ ih₁ ih₂ =>\n      right; cases ih₁ (by rfl) with\n      -- t₁ is a value\n      | inl hv₁ =>\n        cases ih₂ (by rfl) with\n        -- t₂ is a value\n        | inl hv₂ =>\n          cases hv₁ with (inversion h₁)\n          | loc_ l => exists <{ unit }>, ρ.set l t₂; apply Step.assign hv₂; lia\n        -- t₂ steps\n        | inr hs₂ =>\n          have ⟨_, _, _⟩ := hs₂\n          apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n      -- t₁ steps\n      | inr hs₁ =>\n        have ⟨t₁', ρ', hs₁⟩ := hs₁\n        apply Exists.intro; apply Exists.intro; solve_by_elim using StlcRefEval\n\n\n\n\n","context":"Type Systems\u0009References: Typing Mutable References\u0009Properties","header":"9.5.4. Progress","id":"/References/#Type-Systems--References___-Typing-Mutable-References--Properties--Progress"}});